CH = dict(num=9, tag="Maths (Part 2)", theme="Area of rectangles, triangles, polygons, parallelograms, rhombuses, trapeziums; units of area",
 title="Area",
 intro="Area measures how many unit squares fit inside a region. Starting from the rectangle, this chapter builds the area of a triangle, then of any polygon, a parallelogram, a rhombus and a trapezium by cutting and rearranging shapes, and ends with real-life units of area.",
 big_questions=["Why is perimeter not a measure of area?", "How do we get the area of a triangle, and from it the area of any polygon?", "How are the areas of a parallelogram, rhombus and trapezium found by dissection?"],
 blocks=[
 ("h2", "Area of a Rectangle and Why Perimeter Fails"),
 ("note", "FORMULA", "Area of a rectangle = **length × width**. A 9 cm × 6 cm rectangle holds 9 × 6 = **54 unit squares**, so its area is 54 cm²."),
 ("ul", ["The diagonal of a rectangle splits it into **two congruent triangles**, so each has half the area: ½ × 9 × 6 = **27 cm²**.", "Area is measured in **square units** (cm², m²). Perimeter is a length in cm or m, so it cannot measure area."]),
 ("table", ["Rectangle", "Perimeter", "Area"], [["10 cm × 2 cm", "24 cm", "20 cm²"], ["6 cm × 6 cm", "24 cm", "36 cm²"], ["12 cm × 1 cm", "26 cm", "12 cm²"], ["5 cm × 5 cm", "20 cm", "25 cm²"]]),
 ("note", "IMPORTANT", "Same perimeter can give different areas (rows 1 and 2). A **larger perimeter can even give a smaller area** (rows 3 and 4). So perimeter is not a measure of area."),
 ("h3", "Path around a rectangle"),
 ("p", "Outer rectangle 20 m × 14 m, inner park 16 m × 10 m (path 2 m wide all round)."),
 ("note", "FORMULA", "Area of the path = area of outer rectangle − area of inner rectangle = 280 − 160 = **120 m²**."),
 ("h2", "Area of a Triangle"),
 ("note", "FORMULA", "Area of a triangle = **½ × base × height**, where the height is the perpendicular distance from the opposite vertex to the base (or the base extended)."),
 ("ul", ["Any triangle can be placed inside a rectangle with the same base and height; it fills exactly **half** of it.", "For an obtuse triangle, subtract: area = ½ × h × DC − ½ × h × DB = ½ × h × BC.", "Base 12 cm, height 7 cm: area = ½ × 12 × 7 = **42 cm²**."]),
 ("h3", "Finding an altitude"),
 ("p", "In △ABC take BC = 10 cm with altitude AX = 6 cm, and AC = 8 cm."),
 ("steps", [("Step 1 — Area using BC", "½ × 6 × 10 = 30 cm²."), ("Step 2 — Area using AC", "½ × BY × 8 = 4 × BY, where BY is the altitude from B to AC."), ("Step 3 — Equate", "4 × BY = 30, so **BY = 7.5 cm**.")]),
 ("note", "IMPORTANT", "A line joining a vertex to the **midpoint of the opposite side** divides the triangle into two triangles of **equal area** (same height, equal bases). So the four triangles formed by the diagonals of a rectangle have equal areas."),
 ("ul", ["All triangles on the **same base** with the third vertex on a line **parallel to the base** have the **same area**.", "Among them the one with the **least perimeter** has its vertex on the perpendicular bisector of the base (found by reflecting in the parallel line)."]),
 ("h2", "Area of Any Polygon"),
 ("p", "Every polygon can be divided into triangles. Find the area of each triangle and add."),
 ("steps", [("Step 1", "Join vertices with diagonals so that the polygon splits into triangles."), ("Step 2", "Measure a base and its perpendicular height for each triangle."), ("Step 3", "Add the areas of the triangles.")]),
 ("ul", ["Quadrilateral ABCD with diagonal AC = 22 cm and perpendiculars 3 cm and 3 cm from B and D to AC: area = ½ × 22 × 3 + ½ × 22 × 3 = ½ × 22 × (3 + 3) = **66 cm²**.", "Diagonal 18 cm with perpendiculars 5 cm and 7 cm: area = ½ × 18 × (5 + 7) = **108 cm²**."]),
 ("note", "FORMULA", "Quadrilateral = **½ × diagonal × (sum of the two perpendiculars to it)**."),
 ("h2", "Parallelogram"),
 ("p", "Cut a right-angled triangle from one end of the parallelogram and attach it at the other end; the result is a **rectangle** of the same area (base × height)."),
 ("note", "FORMULA", "Area of a parallelogram = **base × height** (height is perpendicular to the base, not the slant side)."),
 ("ul", ["Base 15 cm, height 8 cm: area = **120 cm²**.", "If the other side is 10 cm, the height on that side is 120 ÷ 10 = **12 cm**: any side can be the base with its own height.", "A diagonal divides a parallelogram into two triangles of equal area."]),
 ("h2", "Rhombus"),
 ("note", "FORMULA", "Area of a rhombus = **½ × d₁ × d₂** (product of the diagonals); a rhombus is also a parallelogram, so base × height works."),
 ("ul", ["Diagonals 16 cm and 12 cm: area = ½ × 16 × 12 = **96 cm²**.", "The diagonals bisect each other at right angles, so each side = √(8² + 6²) = **10 cm**.", "Check by triangles: △ADB and △CDB each have area ½ × AO × BD and ½ × CO × BD; their sum is ½ × AC × BD."]),
 ("h2", "Trapezium"),
 ("note", "FORMULA", "Area of a trapezium = **½ × height × (sum of the parallel sides)**."),
 ("ul", ["Parallel sides 9 cm and 15 cm, height 6 cm: area = ½ × 6 × (9 + 15) = **72 cm²**.", "Derivation 1: cut it into a rectangle and two triangles and add the three areas.", "Derivation 2: put two copies together to make a parallelogram of base (a + b) and height h; the trapezium is half of it."]),
 ("table", ["Shape", "Area formula", "Example"], [["Rectangle", "l × w", "9 × 6 = 54"], ["Triangle", "½ × b × h", "½ × 12 × 7 = 42"], ["Parallelogram", "b × h", "15 × 8 = 120"], ["Rhombus", "½ × d₁ × d₂", "½ × 16 × 12 = 96"], ["Trapezium", "½ × h × (a + b)", "½ × 6 × 24 = 72"]]),
 ("h2", "Units of Area in Real Life"),
 ("table", ["Conversion", "Value"], [["1 in", "2.54 cm"], ["1 in²", "2.54² = 6.4516 cm²"], ["10 in²", "64.516 cm²"], ["161.29 cm² in in²", "161.29 ÷ 6.4516 = 25 in²"], ["1 ft", "12 in, so 1 ft² = 144 in²"], ["1 m²", "10,000 cm²"], ["1 km²", "10,00,000 m²"], ["1 acre", "43,560 ft²"]]),
 ("ul", ["An A4 sheet is 21 cm × 29.7 cm = **623.7 cm²**.", "Local units: bigha, gaj, katha, dhur, cent, ankanam. Large regions are measured in **km²**."]),
 ("note", "NOTE", "When converting areas, square the length factor: 1 ft = 12 in gives 1 ft² = 12 × 12 = 144 in², not 12 in²."),
 ("h2", "Common Mistakes"),
 ("table", ["Mistake", "Correct"], [["Using the slant side as the height of a parallelogram", "Use the perpendicular height"], ["Forgetting ½ in the triangle, rhombus or trapezium formula", "Triangle and rhombus have ½ × …; trapezium has ½ × h × (a + b)"], ["Writing area in cm", "Write cm² (square units)"], ["Converting 1 ft² as 12 in²", "1 ft² = 144 in²"]]),
 ("qa", [("Can perimeter measure area?", "No. Different shapes with the same perimeter have different areas, and a larger perimeter can have a smaller area."), ("What is the area of a triangle?", "½ × base × height, with the height perpendicular to the base."), ("How do we find the area of any polygon?", "Divide it into triangles and add their areas."), ("What is the area of a rhombus with diagonals 16 cm and 12 cm?", "½ × 16 × 12 = 96 cm²."), ("Why do all triangles on a common base between two parallel lines have equal area?", "They have the same base and the same height, so ½ × base × height is the same.")]),
 ],
 takeaways=["Area of a rectangle = length × width; perimeter is not a measure of area.", "Triangle: ½ × base × height; a median splits a triangle into two equal-area triangles.", "Triangles on the same base between parallel lines have equal area.", "Any polygon can be divided into triangles; quadrilateral = ½ × diagonal × (sum of perpendiculars).", "Parallelogram = base × height; rhombus = ½ × d₁ × d₂; trapezium = ½ × h × (a + b).", "1 in² = 6.4516 cm²; 1 ft² = 144 in²; 1 km² = 10,00,000 m²; 1 acre = 43,560 ft²."])
